<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: #0f172a;
    color: #e2e8f0;
    min-height: 100vh;
    padding: 32px 24px;
  }

  h1 {
    text-align: center;
    font-size: 1.75rem;
    font-weight: 700;
    letter-spacing: -0.5px;
    margin-bottom: 32px;
    color: #f1f5f9;
  }

  .add-area {
    display: flex;
    gap: 10px;
    justify-content: center;
    margin-bottom: 36px;
  }

  #new-card {
    width: 320px;
    padding: 10px 14px;
    border-radius: 8px;
    border: 1.5px solid #334155;
    background: #1e293b;
    color: #f1f5f9;
    font-size: 0.95rem;
    outline: none;
    transition: border-color 0.15s;
  }

  #new-card::placeholder { color: #64748b; }
  #new-card:focus { border-color: #6366f1; }

  #add-card {
    padding: 10px 20px;
    border-radius: 8px;
    border: none;
    background: #6366f1;
    color: #fff;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s, transform 0.1s;
  }

  #add-card:hover { background: #4f46e5; }
  #add-card:active { transform: scale(0.97); }

  .board {
    display: flex;
    gap: 20px;
    align-items: flex-start;
    justify-content: center;
    flex-wrap: wrap;
  }

  .column {
    background: #1e293b;
    border-radius: 14px;
    width: 300px;
    min-height: 480px;
    display: flex;
    flex-direction: column;
    border: 1.5px solid #334155;
    transition: border-color 0.15s;
  }

  .column.drag-over {
    border-color: #6366f1;
    background: #1e2d47;
  }

  .col-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 18px 12px;
    border-bottom: 1.5px solid #334155;
  }

  .col-header h2 {
    font-size: 0.9rem;
    font-weight: 700;
    letter-spacing: 0.6px;
    text-transform: uppercase;
  }

  #col-todo .col-header h2 { color: #94a3b8; }
  #col-doing .col-header h2 { color: #60a5fa; }
  #col-done .col-header h2 { color: #34d399; }

  .count {
    background: #334155;
    color: #94a3b8;
    font-size: 0.78rem;
    font-weight: 700;
    border-radius: 20px;
    padding: 2px 9px;
    min-width: 26px;
    text-align: center;
  }

  .card-container {
    padding: 12px;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .card {
    background: #0f172a;
    border: 1.5px solid #334155;
    border-radius: 10px;
    padding: 12px 14px;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
    cursor: grab;
    transition: border-color 0.15s, box-shadow 0.15s, transform 0.1s;
    user-select: none;
  }

  .card:hover {
    border-color: #475569;
    box-shadow: 0 4px 16px rgba(0,0,0,0.35);
  }

  .card.dragging {
    opacity: 0.4;
    cursor: grabbing;
    transform: scale(0.98);
  }

  .card-title {
    font-size: 0.9rem;
    line-height: 1.45;
    color: #cbd5e1;
    flex: 1;
    word-break: break-word;
  }

  .card-del {
    background: none;
    border: none;
    color: #475569;
    font-size: 1.1rem;
    line-height: 1;
    cursor: pointer;
    padding: 0 2px;
    border-radius: 4px;
    transition: color 0.15s, background 0.15s;
    flex-shrink: 0;
  }

  .card-del:hover {
    color: #f87171;
    background: rgba(248,113,113,0.1);
  }
</style>
</head>
<body>

<h1>Kanban Board</h1>

<div class="add-area">
  <input id="new-card" type="text" placeholder="New card title…" maxlength="200">
  <button id="add-card">Add Card</button>
</div>

<div class="board">
  <div class="column" id="col-todo">
    <div class="col-header">
      <h2>To Do</h2>
      <span class="count">0</span>
    </div>
    <div class="card-container"></div>
  </div>

  <div class="column" id="col-doing">
    <div class="col-header">
      <h2>In Progress</h2>
      <span class="count">0</span>
    </div>
    <div class="card-container"></div>
  </div>

  <div class="column" id="col-done">
    <div class="col-header">
      <h2>Done</h2>
      <span class="count">0</span>
    </div>
    <div class="card-container"></div>
  </div>
</div>

<script>
  const STORAGE_KEY = 'kanban-board-v1';
  let draggedCard = null;

  function getContainer(colId) {
    return document.querySelector('#' + colId + ' .card-container');
  }

  function updateCount(colId) {
    const col = document.getElementById(colId);
    const count = col.querySelector('.card-container').children.length;
    col.querySelector('.count').textContent = count;
  }

  function saveState() {
    const state = {};
    ['col-todo', 'col-doing', 'col-done'].forEach(colId => {
      const cards = getContainer(colId).querySelectorAll('.card');
      state[colId] = Array.from(cards).map(c => c.dataset.title);
    });
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }

  function createCard(title, colId) {
    const card = document.createElement('div');
    card.className = 'card';
    card.draggable = true;
    card.dataset.title = title;

    const titleEl = document.createElement('span');
    titleEl.className = 'card-title';
    titleEl.textContent = title;

    const delBtn = document.createElement('button');
    delBtn.className = 'card-del';
    delBtn.textContent = '×';
    delBtn.title = 'Delete card';
    delBtn.addEventListener('click', () => {
      const parentCol = card.closest('.column').id;
      card.remove();
      updateCount(parentCol);
      saveState();
    });

    card.addEventListener('dragstart', e => {
      draggedCard = card;
      card.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
    });

    card.addEventListener('dragend', () => {
      card.classList.remove('dragging');
      draggedCard = null;
    });

    card.appendChild(titleEl);
    card.appendChild(delBtn);

    getContainer(colId).appendChild(card);
    updateCount(colId);
  }

  function setupColumn(colId) {
    const col = document.getElementById(colId);

    col.addEventListener('dragover', e => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      col.classList.add('drag-over');
    });

    col.addEventListener('dragleave', e => {
      if (!col.contains(e.relatedTarget)) {
        col.classList.remove('drag-over');
      }
    });

    col.addEventListener('drop', e => {
      e.preventDefault();
      col.classList.remove('drag-over');
      if (!draggedCard) return;

      const sourceCol = draggedCard.closest('.column');
      if (sourceCol.id === colId) return;

      getContainer(colId).appendChild(draggedCard);
      updateCount(sourceCol.id);
      updateCount(colId);
      saveState();
    });
  }

  function loadState() {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return false;
    try {
      const state = JSON.parse(raw);
      ['col-todo', 'col-doing', 'col-done'].forEach(colId => {
        (state[colId] || []).forEach(title => createCard(title, colId));
      });
      return true;
    } catch { return false; }
  }

  // Init columns
  ['col-todo', 'col-doing', 'col-done'].forEach(setupColumn);

  // Load persisted state or seed defaults
  if (!loadState()) {
    createCard('Design mockups', 'col-todo');
    createCard('Write tests', 'col-todo');
    createCard('Build API', 'col-doing');
    createCard('Set up CI', 'col-done');
  }

  // Add card button
  document.getElementById('add-card').addEventListener('click', () => {
    const input = document.getElementById('new-card');
    const title = input.value.trim();
    if (!title) return;
    createCard(title, 'col-todo');
    saveState();
    input.value = '';
    input.focus();
  });

  document.getElementById('new-card').addEventListener('keydown', e => {
    if (e.key === 'Enter') document.getElementById('add-card').click();
  });
</script>
</body>
</html>
